// 清理地图选择界面
void MapSelect_Shutdown(void) {
    printf("Shutting down Map Selection Screen...\n");

    // 清理lay布局上下文
    lay_destroy_context(g_lay_ctx);

    // 清理事件分发器
    UIEventDispatcher_Shutdown(g_event_dispatcher);

    // 清理根容器（会递归清理所有子组件）
    if (g_root_container) {
        UIContainer_Destroy((ui_container_t *)g_root_container);
        g_root_container = NULL;
    }

    // 所有UI组件已经由根容器清理，只需置空指针
    g_ui_list = NULL;
    g_start_button = NULL;
    g_title_text = NULL;
    g_path_text = NULL;
    g_hint_text1 = NULL;
    g_hint_text2 = NULL;
    g_preview_container = NULL;
    g_preview_title_text = NULL;      // "Map Preview"
    g_preview_filename_text = NULL;     // 地图文件名
    g_preview_name_text = NULL;        // 地图名称
    g_preview_author_text = NULL;       // 作者
    g_preview_players_text = NULL;     // 推荐玩家数
    g_preview_type_text = NULL;        // 文件类型
    g_preview_path_text = NULL;       // 完整路径

    if (g_canvas) {
        canvas2d_destroy(g_canvas);
        g_canvas = NULL;
        g_ctx = NULL;
    }

    // 释放地图路径内存
    if (g_start_map_path) {
        free(g_start_map_path);
        g_start_map_path = NULL;
    }

    g_map_count = 0;
    g_state = MAP_SELECT_STATE_INIT;
}

